const MODELO_B64='';

function esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

// keepNext=true mantém o parágrafo junto com o próximo (evita corte entre páginas)
function xmlQuestao(t,keepNext){
  const kn=keepNext?'<w:keepNext/>':'';
  return `<w:p><w:pPr>${kn}<w:spacing w:before="240" w:after="60"/><w:shd w:val="clear" w:color="auto" w:fill="595959"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:b/><w:color w:val="FFFFFF"/><w:sz w:val="22"/><w:szCs w:val="22"/></w:rPr></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:b/><w:color w:val="FFFFFF"/><w:sz w:val="22"/><w:szCs w:val="22"/></w:rPr><w:t>${esc(t)}</w:t></w:r></w:p>`;
}
function xmlAlternativa(t,keepNext){
  const kn=keepNext?'<w:keepNext/>':'';
  return `<w:p><w:pPr>${kn}<w:ind w:left="360"/><w:spacing w:before="0" w:after="28"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr><w:t xml:space="preserve">${esc(t)}</w:t></w:r></w:p>`;
}
function xmlPara(t,keepNext){
  const kn=keepNext?'<w:keepNext/>':'';
  return `<w:p><w:pPr>${kn}<w:jc w:val="both"/><w:spacing w:before="40" w:after="40"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr><w:t xml:space="preserve">${esc(t)}</w:t></w:r></w:p>`;
}
function xmlCriterio(t){return '<w:p><w:pPr><w:pStyle w:val="PargrafodaLista"/><w:jc w:val="both"/><w:spacing w:before="0" w:after="0"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:color w:val="000000"/><w:sz w:val="18"/><w:szCs w:val="18"/></w:rPr><w:t xml:space="preserve">'+esc(t)+'</w:t></w:r></w:p>';}
function xmlVazio(){return '<w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:p>';}

export default async function handler(req,res){
  if(req.method!=='POST') return res.status(405).end();
  try{
    const PizZip=(await import('pizzip')).default;
    const{conteudo,cfg,dadosProva}=req.body;
    const{disc,turma,etapa,serie,criterios,valorInstrumento}=dadosProva;
    const docCode=cfg.docCode||'CE-228';
    const tipoDoc=cfg.tipoDoc||'Prova Objetiva';
    const professor=cfg.nomeProfessora||'';
    const cidade=cfg.cidade||'BOTUCATU';
    const fund1=(serie.includes('EF I')&&!serie.includes('EF II'));
    const fund2=(serie.includes('EF II')||serie.includes('ano EF'));
    const medio=serie.includes('EM');

    const modeloBuffer=Buffer.from(MODELO_B64,'base64');
    const zip=new PizZip(modeloBuffer);
    let xml=zip.file('word/document.xml').asText();

    // Professora
    xml=xml.replace('>a: Sheila Goes<','>a: '+esc(professor)+'<');
    // Cidade
    xml=xml.split('>BOTUCATU<').join('>'+esc(cidade)+'<');
    // Turma combinada
    const serieAbrev=serie.replace(/ano EF I$|ano EF II$| EF I$| EF II$| EM$/,'').trim();
    const turmaCompleta=turma?(serieAbrev+' '+turma):serie;
    xml=xml.replace('<w:t xml:space="preserve">3\u00ba </w:t>','<w:t xml:space="preserve">'+esc(turmaCompleta)+'</w:t>');
    xml=xml.replace('<w:t>A</w:t></w:r><w:r','<w:t></w:t></w:r><w:r');
    // Etapa — remover run "1" via regex, zerar "ª ", inserir etapa
    xml=xml.replace(/(<w:r [^>]*rsidR="00926B12"[^/]*><w:rPr>[\s\S]*?<\/w:rPr><w:t>1<\/w:t><\/w:r>)/,'');
    xml=xml.replace('<w:t xml:space="preserve">\u00aa </w:t>','<w:t></w:t>');
    xml=xml.replace('<w:t>Etapa</w:t>','<w:t>'+esc(etapa||'1\u00aa Etapa')+'</w:t>');
    // CE-228
    xml=xml.replace('<w:t>CE-2</w:t>','<w:t>'+esc(docCode)+'</w:t>');
    xml=xml.replace('<w:t>28</w:t>','<w:t></w:t>');
    // Tipo doc
    xml=xml.replace('<w:t>Prova </w:t>','<w:t>'+esc(tipoDoc)+'</w:t>');
    xml=xml.replace('<w:t>Objetiva</w:t>','<w:t></w:t>');
    // Valor instrumento
    xml=xml.replace('<w:t>Valor do instrumento</w:t>','<w:t>Valor do instrumento: '+esc(valorInstrumento||'10,0')+'</w:t>');
    // Ensino — substituição de MESMO TAMANHO (não desloca etapa)
    const ensinoOrig='Fundamental I         Fundamental II       M\u00e9dio          ';
    if(fund1)      xml=xml.replace(ensinoOrig,'Fundamental I \u2713       Fundamental II       M\u00e9dio          ');
    else if(fund2) xml=xml.replace(ensinoOrig,'Fundamental I         Fundamental II \u2713     M\u00e9dio          ');
    else if(medio) xml=xml.replace(ensinoOrig,'Fundamental I         Fundamental II       M\u00e9dio \u2713        ');

    // Critérios dentro do textbox TB1
    const critList=criterios?criterios.split('\n').filter(c=>c.trim()).map(c=>c.replace(/^[-\u2022*]\s*/,'').trim()):[];
    const critXml=critList.length>0?critList.map(c=>xmlCriterio(c)).join(''):xmlCriterio(' ');
    const idxTB1=xml.indexOf('paraId="0403384B"');
    if(idxTB1>0){
      const pS=xml.lastIndexOf('<w:p ',idxTB1);
      const pE=xml.indexOf('</w:p>',idxTB1)+6;
      xml=xml.slice(0,pS)+critXml+xml.slice(pE);
    }

    // Questões
    const limpo=conteudo.replace(/\*\*([^*]+)\*\*/g,'$1').replace(/\*([^*]+)\*/g,'$1').replace(/__([^_]+)__/g,'$1').replace(/^---+$/gm,'');
    const corpoLinhas=[];let inGab=false;
    for(const l of limpo.split('\n')){
      if(/^GABARITO/i.test(l.trim())){inGab=true;continue;}
      if(!inGab)corpoLinhas.push(l);
    }

    // Classifica linhas em blocos tipados
    const blocos=[];
    for(const l of corpoLinhas){
      const t=l.trim();
      if(!t) blocos.push({tipo:'vazio'});
      else if(/^QUEST[ÃA]O\s+\d+/i.test(t)) blocos.push({tipo:'questao',texto:t});
      else if(/^[A-D]\s*[\)\.]/i.test(t)) blocos.push({tipo:'alt',texto:t});
      else blocos.push({tipo:'para',texto:t});
    }

    // Emite XML: dentro de cada bloco de questão, keepNext em tudo exceto o último elemento
    let questoesXml='';
    let emQuestao=false;
    for(let i=0;i<blocos.length;i++){
      const b=blocos[i];
      if(b.tipo==='vazio'){
        if(!emQuestao) questoesXml+=xmlVazio();
        continue;
      }
      if(b.tipo==='questao'){
        emQuestao=true;
        questoesXml+=xmlQuestao(b.texto,true); // sempre keepNext — sempre seguido de algo
        continue;
      }
      // para ou alt — verifica se há mais linhas no bloco atual (antes da próxima questão)
      let maisNoBloco=false;
      if(emQuestao){
        for(let j=i+1;j<blocos.length;j++){
          if(blocos[j].tipo==='questao') break;
          if(blocos[j].tipo!=='vazio'){maisNoBloco=true;break;}
        }
      }
      if(b.tipo==='alt') questoesXml+=xmlAlternativa(b.texto,maisNoBloco);
      else questoesXml+=xmlPara(b.texto,maisNoBloco);
    }
    const idxL=xml.indexOf('paraId="7BBD12E0"');
    const idxO=xml.indexOf('paraId="0B1A3F30"');
    if(idxL>0&&idxO>0){
      const pL=xml.lastIndexOf('<w:p ',idxL);
      const pO=xml.lastIndexOf('<w:p ',idxO);
      xml=xml.slice(0,pL)+questoesXml+xml.slice(pO);
    }

    zip.file('word/document.xml',xml);
    const output=zip.generate({type:'nodebuffer',compression:'DEFLATE'});
    res.setHeader('Content-Type','application/vnd.openxmlformats-officedocument.wordprocessingml.document');
    res.setHeader('Content-Disposition','attachment; filename="prova_prontoProfe.docx"');
    res.send(output);
  }catch(e){
    console.error('ERRO:',e.message);
    res.status(500).json({error:e.message});
  }
}
